package mz.bam.seeky.android;
public class StudyScheduleTest {
 static int n;static void ok(boolean b,String s){if(!b)throw new AssertionError(s);n++;System.out.println("PASS "+s);}
 public static void main(String[] args){long now=100000;StudySchedule.Next first=StudySchedule.next(now,0,0,0,2);ok(first.interval==1&&first.due==now+86400000,"first remembered review scheduled one day later");StudySchedule.Next second=StudySchedule.next(now,first.interval,first.reps,0,2);ok(second.interval==3,"second remembered review spaced three days");StudySchedule.Next third=StudySchedule.next(now,3,2,0,2);ok(third.interval==7,"later successful review expands interval");StudySchedule.Next again=StudySchedule.next(now,30,5,2,0);ok(again.due==now+60000&&again.reps==0&&again.lapses==3,"forgotten card returns after one minute and increments lapse");ok(StudySchedule.next(now,0,0,0,1).interval==1,"hard first review minimum day");ok(StudySchedule.next(now,10,4,0,1).interval==12,"hard interval grows conservatively");ok(StudySchedule.next(now,0,0,0,3).interval==4,"easy first review four days");ok(StudySchedule.next(now,100,9,0,3).interval==180,"review interval capped at 180 days");try{StudySchedule.next(now,0,0,0,4);throw new AssertionError();}catch(IllegalArgumentException e){ok(true,"reject invalid grading");}ok(StudySchedule.focusSeconds(60000,10000,90000,40000,20,1500)==70,"focus uses elapsed monotonic time plus accumulated pauses");ok(StudySchedule.focusSeconds(20000,100000,120000,60000,0,1500)==60,"focus after reboot falls back to nonnegative wall time");ok(StudySchedule.focusSeconds(10000000,0,10000000,0,0,1500)==1500,"focus cannot exceed planned duration");ok(StudySchedule.focusSeconds(10,100,0,200,0,1500)==0,"clock rollback cannot produce negative focus");ok(StudySchedule.valid("  Álgebra ",80,"Disciplina").equals("Álgebra"),"subject trimming keeps Unicode");try{StudySchedule.valid(" ",20,"Campo");throw new AssertionError();}catch(IllegalArgumentException e){ok(true,"empty user field rejected");}ok(StudySchedule.like("a%_\\b").equals("%a\\%\\_\\\\b%"),"study query escapes wildcard characters");System.out.println(n+" study schedule checks");}
}
